def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for r, row in enumerate(grid):
        cells = [c for c, v in enumerate(row) if v != bg]
        if not cells:
            continue
        color = row[cells[0]]
        if cells == list(range(cells[-1] + 1)) and all(row[c] == color for c in cells) and cells[-1] < len(row) - 1:
            for c in range(cells[-1] + 1, len(row)):
                if row[c] == bg:
                    out[r][c] = 1
    return out
